import{d as u,C as t,o as b,c,j as a,a as s,E as r,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"道德经第六十四章","description":"从未兆微脆到慎终如始，分辨及时照料与强为执持，读欲不欲、学不学。","frontmatter":{"title":"道德经第六十四章","description":"从未兆微脆到慎终如始，分辨及时照料与强为执持，读欲不欲、学不学。","category":"guide","aliases":["道德经第六十四章","老子第六十四章","dao de jing chapter 64"],"source":["王弼《道德真经注》卷四"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-64.md","filePath":"daoism/dao-de-jing/chapter-64.md","lastUpdated":1794189804000}'),g={name:"daoism/dao-de-jing/chapter-64.md"},_=u({...g,setup(p){const o=[{id:"stability-and-before-signs",label:"其安易持，其未兆易谋",showLabel:!0,sentences:[["其安易持，其未",{text:"兆",glossary:"zhao"},"易谋。"]],note:["【白话】事物尚安定时，容易持守；变化还没有显出征兆时，容易谋划。此时已有安定的条件，仍应照料它，不忘可能的变化。","【王弼注择要】「以其安，不忘危。」注用安时不忘危，说明易持易谋为何仍需留意。","【读法】兆为征兆，未兆指尚未显发。不是要求预知一切未来，而是对已有条件、薄弱环节与可能后果保持具体观察。"]},{id:"fragility-and-smallness",label:"其脆易泮，其微易散",showLabel:!0,sentences:[["其",{text:"脆",glossary:"cui"},"易",{text:"泮",glossary:"pan"},"，其微易散。"]],note:["【白话】事情还脆弱时容易解散，还微小时容易疏解。这里着眼于问题尚未坚固、尚未扩大的阶段。","【王弼注择要】「此四者皆说慎终也。」注又说「不可以无之故而不持，不可以微之故而弗散也」，将开头四句共同连到慎终。","【读法】泮为散解，脆微不必泛指一切柔弱生命。经注要求持续照看隐微的变化，不因暂时无事或问题很小便完全放手。"]},{id:"care-before-trouble",label:"为之于未有，治之于未乱",showLabel:!0,sentences:[["为之于未有，治之于未乱。"]],note:["【白话】在事情尚未发生时就作适当准备，在局势尚未混乱时就加以照料。行动的时机要前移，方式仍需合乎事情自身的条件。","【王弼注择要】为之于未有下注「谓其安未兆也」，治之于未乱下注「谓微脆也」，把这两句接回前面四种状态。","【读法】这里的为、治不等于后文受批评的强为和固执；不能把无为理解成对可见问题完全不作回应，也不以防患为名无限干预。"]},{id:"growth-from-small-beginnings",label:"千里之行，始于足下",showLabel:!0,sentences:[[{text:"合抱",glossary:"hebao"},"之木，生于",{text:"毫末",glossary:"haomo"},"；九层之台，起于",{text:"累土",glossary:"leitu"},"；千里之行，始于足下。"]],note:["【白话】两臂合抱的大树，从细如毫末的芽生长；九层高台，从一层层积土筑起；千里行程，从脚下的第一步开始。三种形象都写大由小成、远由近起。","【读法】本段在所据录文未见单独逐句王注。合抱是双臂合围，毫末取极细小之象，累土取积土；结合前后文，也可反观小的疏漏怎样逐步累成难处。","【读法】三喻强调形成的过程，不等于任何微小开端都必然长成宏大结果；后续方向、条件与照料仍会改变走向。"]},{id:"forcing-and-grasping",label:"为者败之，执者失之",showLabel:!0,sentences:[["为者败之，",{text:"执",glossary:"zhi"},"者失之。是以圣人",{text:"无为",glossary:"wuwei"},"故无败，",{text:"无执",glossary:"wuzhi"},"故无失。"]],note:["【白话】以己意强作，反会败坏事情；固执占持，反会失去它。所以圣人不强作，便不因强作而败；不固执，便不因固执而失。","【王弼注择要】注批评「以施为治之，形名执之」，说这样「反生事原」，因而败失。这里把形名固定事物的做法，与慎终除微相对照。","【读法】无为与无执并非免除责任，而是反省照料是否变成主宰。前文及时准备与此处不强作，应在具体行动中同时成立。"]},{id:"near-completion-and-care-to-the-end",label:"慎终如始，则无败事",showLabel:!0,sentences:[["民之从事，常于",{text:"几",glossary:"ji"},"成而败之。",{text:"慎终",glossary:"shenzhong"},"如始，则无败事。"]],note:["【白话】人们做事，常在接近完成时把事情败坏；如果对结尾也像对开头一样慎重，就能避免因失慎而败事。","【王弼注择要】几成而败下注「不慎终也」。这也回应开头把安、未兆、微、脆统归慎终的解释。","【读法】几读 jī，为接近。慎终并不只是最后检查一次，也包括在推进中持续照看条件、在将成时不因松懈或急夺结果而破坏积累。"]},{id:"desiring-not-to-desire",label:"圣人欲不欲",showLabel:!0,sentences:[["是以圣人",{text:"欲不欲",glossary:"yubuyu"},"，不",{text:"贵",glossary:"gui"},"难得之货；"]],note:["【白话】因此圣人以不被欲求牵引为所欲，不抬高难得财货的价值。这里从做事方式回到会滋生争夺的欲求与崇尚。","【王弼注择要】「好欲虽微，争尚为之兴；难得之货虽细，贪盗为之起也。」注把欲尚之微，与后来争盗的滋生相连。","【读法】欲不欲不是取消身体与生活的一切需要，而是反省被人为抬高的欲求；不贵难得之货与第三章相参。"]},{id:"learning-and-assisting-naturalness",label:"以辅万物之自然，而不敢为",showLabel:!0,sentences:[[{text:"学不学",glossary:"xuebuxue"},"，复众人之所过，以",{text:"辅",glossary:"fu"},"万物之",{text:"自然",glossary:"ziran"},"，而不敢为。"]],note:["【白话】学习不以造作求知遮蔽本然的方式，使众人从偏失处复归；以此辅助万物自身的展开，不敢凭己意替它们强定道路。","【王弼注择要】「不学而能者，自然也。」注又说「故学不学，以复众人之所过」，以不待造作而能的自然说明学不学。","【读法】本页依王注区分自然与人为造作，不将学不学直接变成反对教育。辅字保留帮助的行动，不敢为限制的是以己意取代万物自身的展开。"]}],n=[{id:"zhao",term:"兆",sense:1},{id:"cui",term:"脆",sense:1},{id:"pan",term:"泮",sense:1},{id:"hebao",term:"合抱",sense:1},{id:"haomo",term:"毫末",sense:1},{id:"leitu",term:"累土",sense:1},{id:"zhi",term:"执",sense:1},{id:"wuwei",term:"无为",sense:1},{id:"wuzhi",term:"无执",sense:1},{id:"ji",term:"几",sense:1},{id:"shenzhong",term:"慎终",sense:1},{id:"yubuyu",term:"欲不欲",sense:1},{id:"gui",term:"贵",sense:1},{id:"xuebuxue",term:"学不学",sense:1},{id:"fu",term:"辅",sense:1},{id:"ziran",term:"自然",sense:1}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return b(),c("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第六十四章",tabindex:"-1"},[s("道德经第六十四章 "),a("a",{class:"header-anchor",href:"#道德经第六十四章","aria-label":'Permalink to "道德经第六十四章"'},"​")],-1)),r(i,{title:"既要为之于未有，为什么又说为者败之",summary:"本章把尚安、未兆、微脆、渐长与将成几个阶段贯穿起来：既要及时照料，也不能以强为、固执破坏事情。王弼把开头四句总括为慎终，篇末又以辅自然说明欲不欲、学不学。",points:[{label:"先读",text:"未兆与微脆是尚可照料的阶段，王弼并未把它们只当作一次性的开端。"},{label:"再辨",text:"为之于未有与为者败之须分辨行事方式：谨慎养护，与以己意强制、形名固执不同。"},{label:"后看",text:"几成时仍须慎终，最后不以欲与学遮蔽自然，把辅助与主宰分开。"}],hint:"泮读 pàn，为散解；累土读 lěi tǔ，几成的几读 jī。欲不欲、学不学为本章的反转句法，结合篇末辅自然解释。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),r(l,{sections:o,glossary:n}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),r(d,{lines:[{text:"为之于未有，治之于未乱。",tone:"前移照料的时机",guide:"依王注接回安未兆、微脆，仍要分辨适当准备与强作。"},{text:"慎终如始，则无败事。",tone:"从始至终的同一慎重",guide:"将成时的松懈或强夺结果，都可能损伤此前积累。"},{text:"以辅万物之自然，而不敢为。",tone:"辅助而不替代",guide:"篇末仍有辅的行动，也限制以自己的图式主宰事物。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),r(h,{items:n}),e[4]||(e[4]=m("",15))])}}});export{y as __pageData,_ as default};
